&lt;p&gt;&lt;span style=&quot;text-indent: -27.6px; letter-spacing: 0pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;□&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;2026&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;년&amp;nbsp;&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;1/4&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;분기말&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;예금취급기관&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;의&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;; vertical-align: super;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;산업별대출금 잔액&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;은&amp;nbsp;&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;2,061.8&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;조원&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; letter-spacing: -0.4pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;으로&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;text-indent: -27.6px; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;전분기말 대비&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;text-indent: -27.6px; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;text-indent: -27.6px; letter-spacing: 0pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;35.6&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;조원 증가&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;하였으며 전분기&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;text-indent: -27.6px; letter-spacing: 0pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;(+8.5&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;조원&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;text-indent: -27.6px; letter-spacing: 0pt; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;text-indent: -27.6px; font-size: 10pt; font-family: &#39;맑은 고딕&#39;;&quot;&gt;에 비해 증가폭이 확대&lt;/span&gt;&lt;/p&gt;
&lt;p class=&quot;0&quot; style=&quot;margin-left: 35pt; font-family: &#39;Noto Sans KR&#39;, 맑은고딕, &#39;malgun gothic&#39;, AppleGothic, 돋움, dotum, Helvetica, Arial, sans-serif; background-color: rgb(255, 255, 255); text-indent: -35pt; font-size: 11pt;&quot;&gt;&lt;span style=&quot;font-weight: bold; font-family: &#39;맑은 고딕&#39;; font-size: 10pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
